"""
Disctname
"""
import json
import os
import re
from builtins import object
from taf.ul.trs_e2e_fw.lib.oam.exceptions import ParamNotSupportedException
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.scf_parser.scf_parser import ScfParser
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable

logger = BackgroundLogger.Instance()
INFOMODEL_CLASSNAMES = 'infomodel_classnames.json'


class DistNames(object):
    """
    DistNames
    """

    def __init__(self, admin, admin_infomodel, config):
        self.admin = admin
        self.admin_infomodel = admin_infomodel
        self.config = config
        self._load_infomodel_classnames_json()

    def get_full_distname_from_scf(self, distname_suffix, format_distname=True, alias='default'):
        """
        Function to get full distname from scf
        """
        scf_parser = self._get_scf_parser(alias=alias)
        scf_distname = scf_parser.get_full_distname(distname_suffix)
        if format_distname is True:
            return self.format_distname(scf_distname, alias=alias)
        return scf_distname

    def format_distname(self, scf_distname, alias):
        """
        Function to format distname
        """
        scf_distname = scf_distname.replace('-', '_A-')
        full_distname = self.prepend_distname_prefix(scf_distname, alias)
        logger.debug('formatted distname: {}'.format(full_distname))
        return full_distname

    # def format_to_infomodel_compatible_distname(self, distname):
    #     if '_A-' not in distname:
    #         distname = '//' + distname
    #         distname = distname.replace('-', '_A-')
    #     return distname

    def format_to_infomodel_compatible_distname(self, distname):
        """
        Function to format to infomodel compatible distname
        """
        pattern = re.compile(r'_[ARLM]-')
        if not re.search(pattern, distname):
            distname = '//' + distname
            distname = distname.replace('-', '_A-')
        return distname

    def prepend_distname_prefix(self, distname, alias):
        """
        Function to prepend distname prefix
        """
        # prefix = '/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-1/SCF-1/'
        prefix = self._get_prefix_with_currentnp(alias)
        if prefix not in distname:
            full_distname = '{}{}'.format(prefix, distname)
            return full_distname
        return distname

    def _get_prefix_with_currentnp(self, alias):
        """
        FUnction to get prefix with current np
        """
        # bts_conf_distname = '/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1'
        bts_conf_distname = '/MRBTS-1//BTS_CONF-1'
        param_dict = self.admin_infomodel.get_infomodel_object(dist_name=bts_conf_distname,
                                                               timeout=20, alias=alias)
        prefix = param_dict.get('currentNp', '/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-1')
        prefix = prefix + '/SCF-*/'
        return prefix

    def get_distname_and_param(self, parameter, moc_num=None):
        """
        Function to get dictname and parameter
        """
        try:
            distname = get_config_variable(['distnames', parameter])
        except KeyError:
            raise ParamNotSupportedException('Add entry in distnames.json')
        if moc_num is not None:
            distname = distname.format(moc_num=moc_num)
        return distname

    def get_distnames_of_all_configured_cells(self, alias, timeout):
        """
        Function to get distnames of all configured cells
        """
        distnames_dict = {}
        for rat in get_config_variable(['rat_env_without_common']):
            try:
                class_content = self.admin.get_managed_objects(class_name=self.infomodel_classnames_dict[rat],
                                                               timeout=float(timeout), connection=alias)
                # class_content = self.admin.get_parameters_for_all(class_name=self.infomodel_classnames_dict[rat],
                # timeout=float(timeout), connection=alias)
                # Do Nothing if class not found. Raise exceptions for other cases.
                # Comment to be removed later
                distnames_dict[rat] = self._extract_infomodel_distnames(class_content)
            except KeyError:
                logger.warn('5G Cell Based Operations To Be Implemented')
        return distnames_dict

    def _extract_infomodel_distnames(self, class_content):
        """
        Function to extract infomodel distnames
        """
        dist_names_list = []
        for class_item in class_content:
            distname = class_item["distName"]
            if 'GNCEL_M' in distname:
                # For GSM Cells, the suffix GNCEL_M- is not needed
                distname = re.sub(r"/GNCEL_M-\d+", "", distname)
            dist_names_list.append(distname)
        return dist_names_list

    def _extract_infomodel_distnames_new(self, class_content):
        """
        Function to extract infomodel distnames
        """
        dist_names_list = []
        for class_item in class_content:
            distname = class_item["id"]
            if 'GNCEL_M' in distname:
                # For GSM Cells, the suffix GNCEL_M- is not needed
                distname = re.sub(r"/GNCEL_M-\d+", "", distname)
            dist_names_list.append(distname)
        logger.debug("TAF::Extracted distnames are {}".format(dist_names_list))
        return dist_names_list

    def _load_infomodel_classnames_json(self):
        """
        Function to load extract infomodel distnames
        """
        classes_file = os.path.abspath(os.path.join(__file__, os.pardir, 'resources',
                                                    INFOMODEL_CLASSNAMES))
        with open(classes_file) as json_file:
            self.infomodel_classnames_dict = json.load(json_file)

    def _get_scf_parser(self, alias):
        """
        Function to get scf parser
        """
        from taf.ul.trs_e2e_fw.lib.oam.admin.utils import _generate_scf
        if alias not in list(global_vars.alias_scf_dict.keys()):
            scf_file = _generate_scf(alias)
        else:
            scf_file = global_vars.alias_scf_dict[alias]
        return ScfParser(scf_file)
